type UnescapedCookieParamError struct {
	ParamName string
	Err       error
}

func (e *UnescapedCookieParamError) Error() string {
	return fmt.Sprintf("error unescaping cookie parameter '%s'", e.ParamName)
}

func (e *UnescapedCookieParamError) Unwrap() error {
	return e.Err
}

type UnmarshalingParamError struct {
	ParamName string
	Err       error
}

func (e *UnmarshalingParamError) Error() string {
	return fmt.Sprintf("Error unmarshaling parameter %s as JSON: %s", e.ParamName, e.Err.Error())
}

func (e *UnmarshalingParamError) Unwrap() error {
	return e.Err
}

type RequiredParamError struct {
	ParamName string
}

func (e *RequiredParamError) Error() string {
	return fmt.Sprintf("Query argument %s is required, but not found", e.ParamName)
}

type RequiredHeaderError struct {
	ParamName string
	Err       error
}

func (e *RequiredHeaderError) Error() string {
	return fmt.Sprintf("Header parameter %s is required, but not found", e.ParamName)
}

func (e *RequiredHeaderError) Unwrap() error {
	return e.Err
}

type InvalidParamFormatError struct {
	ParamName string
	Err       error
}

func (e *InvalidParamFormatError) Error() string {
	return fmt.Sprintf("Invalid format for parameter %s: %s", e.ParamName, e.Err.Error())
}

func (e *InvalidParamFormatError) Unwrap() error {
	return e.Err
}

type TooManyValuesForParamError struct {
	ParamName string
	Count     int
}

func (e *TooManyValuesForParamError) Error() string {
	return fmt.Sprintf("Expected one value for %s, got %d", e.ParamName, e.Count)
}

// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/client-config", wrapper.GetClientConfig)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/version", wrapper.GetVersion)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/me", wrapper.GetMe)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/slots", wrapper.GetSlots)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/slots/refresh", wrapper.RefreshSlots)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/invitations", wrapper.ListInvitations)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/invitations", wrapper.Invite)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v1/invitations/{email}", wrapper.WithdrawInvitation)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/release-notes", wrapper.ListReleaseNotes)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/release-notes/read", wrapper.MarkReleaseNotesRead)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/groups", wrapper.ListGroups)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/groups", wrapper.CreateGroup)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/groups/{groupId}", wrapper.GetGroup)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v1/groups/{groupId}", wrapper.UpdateGroup)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/groups/{groupId}/invitations", wrapper.InviteToGroup)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v1/groups/{groupId}/invitations/{email}", wrapper.DropGroupInvitation)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/groups/{groupId}/join", wrapper.JoinGroup)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v1/groups/{groupId}/members/{email}", wrapper.RemoveFromGroup)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/groups/{groupId}/members/{email}", wrapper.AdmitToGroup)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v1/groups/{groupId}/requests/{email}", wrapper.DropJoinRequest)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/me/name", wrapper.SetMyName)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/availability", wrapper.GetAvailability)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/availability/days/{day}", wrapper.SetAvailabilityDay)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/availability/templates", wrapper.SetAvailabilityTemplates)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/availability/venues", wrapper.SetVenues)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/groups/{groupId}/fits", wrapper.ListFits)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/groups/{groupId}/games", wrapper.ProposeGame)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/games", wrapper.ListGames)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/games/{gameId}", wrapper.GetGame)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v1/games/{gameId}", wrapper.UpdateGame)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/games/{gameId}/players/me", wrapper.AnswerGame)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/push", wrapper.GetPush)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v1/push/subscriptions/{subscriptionId}", wrapper.UnsubscribePush)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/push/subscriptions/{subscriptionId}", wrapper.SubscribePush)
	})

	return r
}

